<?php
if (!defined('ABSPATH')) { exit(1); }
wp_set_current_user(get_user_by('login','qa_admin')->ID);
$checks=0;$check=function($ok,$label)use(&$checks){if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;};
$repo=new SuiteEdge\Migrator\Jobs\JobRepository();$runner=new SuiteEdge\Migrator\Jobs\BatchRunner($repo);
$source=(new SuiteEdge\Migrator\Import\SourceRepository())->save(wp_json_encode(['data'=>'[et_pb_text custom_css_main="color:red;" scroll_horizontal_motion_enable="on" scroll_horizontal_motion="0|50|50|100|-5|0|0"]Portable[/et_pb_text]']),'motion.json');
$page=wp_insert_post(['post_type'=>'page','post_title'=>'Motion integration target','post_status'=>'publish','post_content'=>'Original']);
$before=(new SuiteEdge\Migrator\Import\BackupEngine())->state($page);
$job=new SuiteEdge\Migrator\Jobs\Job();$job->settings=['output_engine'=>'classic','dry_run'=>false,'assets'=>[],'reviewed_warnings'=>false];
$job->items=[['source_id'=>$source,'layout_index'=>0,'name'=>'motion.json','target_page_id'=>$page,'status'=>'pending']];$job->summary['total']=1;$repo->save($job);
$check($runner->process_batch($job->id)['status']==='completed','published target with supported effects and styling applies without acknowledging informational notes');
$saved=$repo->get($job->id);
$check($saved->summary['warnings']===0&&empty($saved->items[0]['warnings']),'only actionable warnings counted');
$check(count($saved->items[0]['information'])===3&&count(array_filter($saved->items[0]['information'],function($note){return strpos($note,'Export scope:')===0;}))===1,'styles, motion and page export scope information persisted with job');
$report=(new SuiteEdge\Migrator\Reports\ReportBuilder())->build($saved);
$check($report['diagnostics']['counts']===['error'=>0,'warning'=>0,'info'=>3],'report has explicit severity counts including nonblocking page scope');
$check(strpos($report['outcome']['message'],'1 page converted.')===0,'singular outcome correctly describes applied page');
$data=json_decode(get_post_meta($page,'_elementor_data',true),true);
$check(strpos(wp_json_encode($data),'SuiteEdgePortableEffects')!==false,'portable runtime survives Elementor metadata write');
$html=Elementor\Plugin::$instance->frontend->get_builder_content_for_display($page,true);
$check(strpos($html,'<script>')!==false&&strpos($html,'"horizontal"')!==false,'actual Elementor HTML widget renders runtime');
$check($runner->rollback($job->id)['status']==='rolled_back'&&(new SuiteEdge\Migrator\Import\BackupEngine())->state($page)===$before,'motion page rollback restores original exactly');
$legacy=new SuiteEdge\Migrator\Jobs\Job();$legacy->status='completed';$legacy->settings=['dry_run'=>false];
$legacy->items=[['name'=>'legacy','status'=>'converted','target_page_id'=>219,'warnings'=>['et_pb_section: supplemental scoped CSS stored in an editable Elementor HTML widget; review selectors and fonts visually.','et_pb_section: unmapped setting retained in source export; review parallax','Image tooltip title retained in source metadata; review the imported attachment title. Divi image titles do not create visible captions.']]];$legacy->summary['warnings']=3;
$report=(new SuiteEdge\Migrator\Reports\ReportBuilder())->build($legacy);
$check($report['diagnostics']['counts']===['error'=>0,'warning'=>2,'info'=>1],'historical styling notes classified, actual old motion/title losses remain warnings');
$check($report['summary']['warnings']===3&&count($report['pages'][0]['warnings'])===3,'legacy raw history and counts preserved');
$check($report['diagnostics']['entries'][1]['code']==='unmapped_setting'&&strpos($report['diagnostics']['entries'][1]['action'],'not applied')!==false,'unmapped cause has concrete corrective action');
$legacy->status='completed_with_errors';$legacy->items[0]['status']='failed';$legacy->items[0]['error']='Published target is protected: review warnings';
$report=(new SuiteEdge\Migrator\Reports\ReportBuilder())->build($legacy);
$check($report['outcome']['status_label']==='Conversion not applied'&&strpos($report['outcome']['message'],'No pages were converted.')===0,'failed apply cannot imply successful completion');
$check($report['diagnostics']['counts']['error']===1&&end($report['diagnostics']['entries'])['code']==='published_target_guard','protected target explains required review step');
$legacy->items[0]['error']='Unexpected issue';$legacy->items[0]['warnings']=['Unknown future warning'];
$report=(new SuiteEdge\Migrator\Reports\ReportBuilder())->build($legacy);
$check($report['diagnostics']['counts']===['error'=>1,'warning'=>1,'info'=>0],'unknown diagnostic messages fail closed as actionable');
$export=(new SuiteEdge\Migrator\Import\DiviExportReader())->read_file(getenv('SUITEEDGE_HOME_FIXTURE'));
$links=json_decode(file_get_contents(getenv('SUITEEDGE_HOME_LINKS')),true)['links'];$builder=new SuiteEdge\Migrator\Elementor\DocumentBuilder();
$home=(new SuiteEdge\Migrator\Elementor\Classic\Serializer())->serialize($builder->build($export['post_content'],['presets'=>$export['presets'],'link_map'=>$links,'source_origin'=>'https://suiteedge.com']));
$check(empty($builder->warnings),'real Home remaining warnings resolved through actual adapters');
$carrier=end($home[0]['elements'])['settings']['html'];
preg_match('/\}\)\s*(\(\[.*\]\));<\/script>$/s',$carrier,$match);
$config=json_decode(substr($match[1]??'',1,-1),true);
$check(is_array($config)&&count($config)===27,'real Home runtime has five backgrounds, one enabled horizontal effect and all image tooltips');
$check(count(array_filter($config,function($e){return isset($e['effects']['parallax']);}))===5,'all five true/CSS parallax backgrounds covered');
$check(count(array_filter($config,function($e){return isset($e['effects']['horizontal']);}))===1,'inactive column curves never enabled');
$check(count(array_filter($config,function($e){return isset($e['effects']['image_title']);}))===21,'all 21 image tooltips covered');
$check(count(array_filter($builder->information,function($m){return strpos($m,'source effect is disabled')!==false;}))===6,'six inactive column settings recorded accurately');
file_put_contents(ABSPATH.'../motion-wordpress-results'.(defined('DB_ENGINE')?'-sqlite':'-mariadb').'.json',wp_json_encode(['assertions'=>$checks,'plugin'=>SUITEEDGE_MIGRATOR_VERSION,'database'=>defined('DB_ENGINE')?DB_ENGINE:$GLOBALS['wpdb']->db_version(),'home_warnings'=>$builder->warnings,'home_information'=>array_values(array_unique($builder->information)),'portable_effects'=>$config],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));
echo 'PASS: '.$checks.' WordPress motion/diagnostic assertions'.PHP_EOL;
